package com.homa.reservation.domain;

import java.util.Objects;
import java.util.UUID;

/** A checkout's identity, generated by the domain. Payment reports the payment against it (RES-11). */
public record CheckoutId(String value) {

    public CheckoutId {
        Objects.requireNonNull(value, "value");
    }

    public static CheckoutId generate() {
        return new CheckoutId(UUID.randomUUID().toString());
    }
}
